#!/usr/bin/env node
// Renders spec/math-ops.json — the authored math-operation manifest — into every
// host's math-plan vocabulary table and into docs/internals/math-ops.md.
//
//     node tools/gen-math-ops.mjs            write the generated files
//     node tools/gen-math-ops.mjs --check    validate and diff, write nothing
//
// The renderings ARE committed (see tools/gen-builtins.mjs for why). Each
// host's math-plan compiler classifies source nodes through its rendering and
// maps the symbolic operation to its own opcode; opcode numbers, enums and
// keywords stay native and are not in the manifest. Every builtin the manifest
// names is checked against spec/builtins.json here, so the two authored
// sources cannot disagree about an arity.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = 'spec/math-ops.json';
const BUILTINS = 'spec/builtins.json';

const OUTPUTS = {
  js: 'js/src/_math_ops.mjs',
  python: 'python/sel/_math_ops.py',
  php: 'php/src/MathOps.php',
  cpp: 'cpp/sel_math_ops.hpp',
  lisp: 'lisp/src/math-ops.lisp',
  docs: 'docs/internals/math-ops.md',
};

const HEADER = `GENERATED by tools/gen-math-ops.mjs from ${SOURCE} — do not edit; edit the manifest and regenerate.`;

function fail(msg) {
  process.stderr.write(`gen-math-ops: ${msg}\n`);
  process.exit(1);
}

function load() {
  const doc = JSON.parse(readFileSync(resolve(ROOT, SOURCE), 'utf8'));
  const builtins = JSON.parse(readFileSync(resolve(ROOT, BUILTINS), 'utf8')).builtins;
  const ops = doc.operations;
  if (!ops || typeof ops !== 'object') fail('"operations" must be an object');
  const out = [];
  const seenSource = new Set();
  for (const [name, e] of Object.entries(ops)) {
    const where = (k) => `${name}.${k}`;
    if (!/^[A-Z][A-Z0-9_]*$/.test(name)) fail(`${name}: an operation name is upper-case ASCII`);
    for (const k of Object.keys(e)) if (!['source', 'arity', 'auxPosition'].includes(k)) fail(`${where(k)}: unknown key`);
    const s = e.source;
    if (!s || typeof s !== 'object' || Object.keys(s).length !== 1) fail(`${where('source')}: exactly one of operator, prefix, builtin`);
    const [kind, token] = Object.entries(s)[0];
    if (!['operator', 'prefix', 'builtin'].includes(kind)) fail(`${where('source')}: unknown kind "${kind}"`);
    if (typeof token !== 'string' || token === '') fail(`${where('source.' + kind)}: a non-empty string`);
    const key = `${kind}:${token}`;
    if (seenSource.has(key)) fail(`${where('source')}: ${kind} ${token} is claimed twice`);
    seenSource.add(key);
    const arity = e.arity;
    if (arity !== 1 && arity !== 2 && arity !== 'fold') fail(`${where('arity')}: 1, 2 or "fold"`);
    if (kind === 'operator' && arity !== 2) fail(`${where('arity')}: a binary operator has two operands`);
    if (kind === 'prefix' && arity !== 1) fail(`${where('arity')}: a prefix operator has one operand`);
    if (e.auxPosition !== undefined) {
      if (arity !== 2 || kind !== 'builtin') fail(`${where('auxPosition')}: only a two-operand builtin has one`);
      if (e.auxPosition !== 0 && e.auxPosition !== 1) fail(`${where('auxPosition')}: 0 or 1`);
    }
    if (kind === 'builtin') {
      const b = builtins[token];
      if (!b) fail(`${where('source.builtin')}: ${token} is not in ${BUILTINS}`);
      if (b.lazy) fail(`${where('source.builtin')}: ${token} is lazy; a plan cannot evaluate its arguments for it`);
      const min = b.arity.min;
      const max = b.arity.max === 'variadic' ? Infinity : b.arity.max;
      if (arity === 'fold') {
        if (min !== 1 || max !== Infinity) fail(`${where('arity')}: a fold needs ${token} to accept 1 or more arguments, it accepts ${min}..${max}`);
      } else if (min !== arity || max !== arity) {
        fail(`${where('arity')}: ${token} takes ${min}..${max} arguments, not exactly ${arity}`);
      }
    }
    out.push({ name, kind, token, arity, aux: e.auxPosition ?? null });
  }
  return out;
}

const jsStr = (s) => JSON.stringify(s);
const pyStr = (s) => "'" + s.replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
const phpStr = pyStr;
const cppStr = (s) => '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const lispStr = cppStr;

function renderJs(ops) {
  const l = [`// ${HEADER}`, '//',
    '// What the math plan compiles: MATH_OPERATORS maps a binary operator token and',
    '// MATH_PREFIX a prefix operator name to a symbolic operation; MATH_BUILTINS',
    "// maps a builtin name to { op, arity (1 | 2 | 'fold'), aux }. MATH_OPS lists",
    '// every operation; math_plan.mjs maps each to its own opcode and refuses to',
    '// load if one is missing.', '',
    'export const MATH_OPERATORS = Object.freeze({'];
  for (const o of ops) if (o.kind === 'operator') l.push(`  ${jsStr(o.token)}: ${jsStr(o.name)},`);
  l.push('});', '', 'export const MATH_PREFIX = Object.freeze({');
  for (const o of ops) if (o.kind === 'prefix') l.push(`  ${jsStr(o.token)}: ${jsStr(o.name)},`);
  l.push('});', '', 'export const MATH_BUILTINS = Object.freeze({');
  for (const o of ops) if (o.kind === 'builtin') l.push(`  ${jsStr(o.token)}: { op: ${jsStr(o.name)}, arity: ${jsStr(o.arity)}, aux: ${o.aux === null ? 'null' : o.aux} },`);
  l.push('});', '', `export const MATH_OPS = Object.freeze([${ops.map((o) => jsStr(o.name)).join(', ')}]);`, '');
  return l.join('\n');
}

function renderPython(ops) {
  const l = [`# ${HEADER}`, '#',
    '# What the math plan compiles: MATH_OPERATORS maps a binary operator token and',
    '# MATH_PREFIX a prefix operator name to a symbolic operation; MATH_BUILTINS',
    "# maps a builtin name to (op, arity 1 | 2 | 'fold', aux). MATH_OPS lists every",
    '# operation; math_plan.py maps each to its own OpCode and refuses to import if',
    '# one is missing.', '',
    'MATH_OPERATORS = {'];
  for (const o of ops) if (o.kind === 'operator') l.push(`    ${pyStr(o.token)}: ${pyStr(o.name)},`);
  l.push('}', '', 'MATH_PREFIX = {');
  for (const o of ops) if (o.kind === 'prefix') l.push(`    ${pyStr(o.token)}: ${pyStr(o.name)},`);
  l.push('}', '', 'MATH_BUILTINS = {');
  for (const o of ops) if (o.kind === 'builtin') l.push(`    ${pyStr(o.token)}: (${pyStr(o.name)}, ${typeof o.arity === 'string' ? pyStr(o.arity) : o.arity}, ${o.aux === null ? 'None' : o.aux}),`);
  l.push('}', '', `MATH_OPS = (${ops.map((o) => pyStr(o.name)).join(', ')})`, '');
  return l.join('\n');
}

function renderPhp(ops) {
  const l = ['<?php', `// ${HEADER}`, '//',
    '// What the math plan compiles: OPERATORS maps a binary operator token and',
    '// PREFIX a prefix operator name to a symbolic operation; BUILTINS maps a',
    "// builtin name to [op, arity 1 | 2 | 'fold', aux]. OPS lists every operation;",
    '// MathPlan.php maps each to its own MathOpCode and refuses to load if one is',
    '// missing.', '',
    'declare(strict_types=1);', '', 'namespace Sel;', '', 'final class MathOps', '{',
    '    /** @var array<string,string> */', '    public const OPERATORS = ['];
  for (const o of ops) if (o.kind === 'operator') l.push(`        ${phpStr(o.token)} => ${phpStr(o.name)},`);
  l.push('    ];', '', '    /** @var array<string,string> */', '    public const PREFIX = [');
  for (const o of ops) if (o.kind === 'prefix') l.push(`        ${phpStr(o.token)} => ${phpStr(o.name)},`);
  l.push('    ];', '', '    /** @var array<string, array{0:string,1:int|string,2:int|null}> */', '    public const BUILTINS = [');
  for (const o of ops) if (o.kind === 'builtin') l.push(`        ${phpStr(o.token)} => [${phpStr(o.name)}, ${typeof o.arity === 'string' ? phpStr(o.arity) : o.arity}, ${o.aux === null ? 'null' : o.aux}],`);
  l.push('    ];', '', '    /** @var list<string> */', `    public const OPS = [${ops.map((o) => phpStr(o.name)).join(', ')}];`, '}', '');
  return l.join('\n');
}

function renderCpp(ops) {
  const l = [`// ${HEADER}`, '//',
    '// What the math plan compiles: one entry per operation with its source kind',
    '// (1 binary operator, 2 prefix operator, 3 builtin), its token, its operand',
    '// count (1, 2, or 0 for a left fold of one or more) and the auxiliary error',
    '// position argument (-1 when none). sel.cpp maps each name to its MathOp and',
    '// refuses to start if one is missing.',
    '#pragma once', '', 'namespace sel_math_ops {', '',
    'struct Op {', '  const char* name;', '  int kind;', '  const char* token;', '  int arity;', '  int aux;', '};', '',
    'inline const Op OPS[] = {'];
  for (const o of ops) l.push(`  {${cppStr(o.name)}, ${{ operator: 1, prefix: 2, builtin: 3 }[o.kind]}, ${cppStr(o.token)}, ${o.arity === 'fold' ? 0 : o.arity}, ${o.aux === null ? -1 : o.aux}},`);
  l.push('};', '', `inline constexpr int COUNT = ${ops.length};`, '', '}  // namespace sel_math_ops', '');
  return l.join('\n');
}

function renderLisp(ops) {
  const l = [`;;;; ${HEADER}`, ';;;;',
    ';;;; What the math plan compiles: one list per operation, (name kind token arity',
    ';;;; aux) with kind :operator | :prefix | :builtin, arity 1 | 2 | :fold and aux',
    ';;;; NIL or the auxiliary-position argument. math-plan.lisp maps each name to',
    ';;;; its keyword and refuses to load if the executor lacks one.', '',
    '(in-package #:sel)', '', '(setf *math-op-data*', "      '("];
  for (const o of ops) l.push(`        (${lispStr(o.name)} :${o.kind} ${lispStr(o.token)} ${o.arity === 'fold' ? ':fold' : o.arity} ${o.aux === null ? 'nil' : o.aux})`);
  l[l.length - 1] += '))';
  l.push('');
  return l.join('\n');
}

function renderDocs(ops) {
  const l = [`<!-- ${HEADER} -->`, '# Math-plan operations', '',
    'The operations every host\'s math plan compiles, from the authored manifest',
    '`spec/math-ops.json` (format: `spec/math-ops.md`). A pure-arithmetic subtree',
    'made only of these, number literals and variables runs as a flat plan instead',
    'of an AST walk; anything else in it becomes a leaf the plan evaluates the',
    'ordinary way. Opcode numbers are each host\'s own and are not listed.', '',
    '| Operation | Source | Operands | Error positions |', '|---|---|---|---|'];
  for (const o of ops) {
    const src = o.kind === 'operator' ? `binary \`${o.token}\`` : o.kind === 'prefix' ? `prefix \`${o.token}\`` : `\`${o.token}(…)\``;
    const n = o.arity === 'fold' ? '1 or more, folded left to right' : String(o.arity);
    const pos = o.aux === null ? 'the operator or call' : `the call; argument ${o.aux + 1} for its own errors`;
    l.push(`| \`${o.name}\` | ${src} | ${n} | ${pos} |`);
  }
  l.push('', `${ops.length} operations.`, '');
  return l.join('\n');
}

const ops = load();
const rendered = {
  js: renderJs(ops), python: renderPython(ops), php: renderPhp(ops),
  cpp: renderCpp(ops), lisp: renderLisp(ops), docs: renderDocs(ops),
};
if (process.argv.includes('--check')) {
  let stale = 0;
  for (const [host, path] of Object.entries(OUTPUTS)) {
    let current = null;
    try { current = readFileSync(resolve(ROOT, path), 'utf8'); } catch { /* missing */ }
    if (current !== rendered[host]) { process.stderr.write(`gen-math-ops: ${path} is ${current === null ? 'missing' : 'stale'}\n`); stale++; }
  }
  if (stale) process.exit(1);
  process.stdout.write(`gen-math-ops: ${ops.length} operations, ${Object.keys(OUTPUTS).length} renderings current\n`);
} else {
  for (const [host, path] of Object.entries(OUTPUTS)) {
    writeFileSync(resolve(ROOT, path), rendered[host]);
    process.stdout.write(`wrote ${path}\n`);
  }
}
